function validate([batteryPercentages]) {
  if (!Array.isArray(batteryPercentages) || batteryPercentages.length < 1 || batteryPercentages.length > 100) return 'batteryPercentages needs 1 to 100 values.';
  if (batteryPercentages.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each battery level is an integer from 0 to 100.';
  return null;
}

