function countTestedDevices(batteryPercentages) {
  const levels = batteryPercentages.slice();
  let count = 0;
  for (let i = 0; i < levels.length; i++) {
    if (levels[i] <= 0) continue;
    count++;
    for (let j = i + 1; j < levels.length; j++) levels[j] = Math.max(0, levels[j] - 1);
  }
  return count;
}

